parameters.jsCode:
// One Slack message per run. Error rows (a place LinkedIn couldn't find, a search
// it refused) are listed at the bottom so a broken search doesn't look like a quiet day.
const items = $input.all().map((i) => i.json);
const jobs = items.filter((j) => j.type === 'job');
const failed = items.filter((j) => j.type === 'error');
if (!jobs.length && !failed.length) return [];

const money = (j) => {
  if (j.salaryMin == null) return '';
  const k = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : `${n}`);
  const cur = j.salaryCurrency === 'USD' ? '$' : `${j.salaryCurrency ?? ''} `;
  const range = j.salaryMax && j.salaryMax !== j.salaryMin ? `${cur}${k(j.salaryMin)}–${k(j.salaryMax)}` : `${cur}${k(j.salaryMin)}`;
  return ` · ${range}${j.salaryPeriod === 'hour' ? '/hr' : ''}`;
};
const lines = jobs.slice(0, 30).map((j) => {
  const applied = j.applicantCount != null ? ` · ${j.applicants}` : (j.applicants ? ` · ${j.applicants}` : '');
  return `• <${j.jobUrl}|${j.title}> at *${j.companyName}*, ${j.location}${money(j)}${applied}`;
});
const more = jobs.length > 30 ? [`…and ${jobs.length - 30} more.`] : [];
const errors = failed.map((e) => `:warning: ${e.searchKeywords ?? ''} ${e.searchLocation ? `in ${e.searchLocation}` : ''}: ${e.errorDescription}`);
const head = jobs.length ? `*${jobs.length} new LinkedIn job${jobs.length === 1 ? '' : 's'}*` : '*No new LinkedIn jobs*';
return [{ json: { text: [head, ...lines, ...more, ...errors].join('\n'), newJobs: jobs.length } }];
